def bi(en,zh): return {'en':en,'zh':zh}
def question(code,en,zh,options,answer,ref):
 return dict(code=code,prompt=bi(en,zh),options=[{'id':str(i),'text':bi(*v)} for i,v in enumerate(options)],answer=str(answer),rule_ref=ref)
D='https://www.dropbox.com/scl/fi/obj1v4l91tdpu998cmwky/DC_Rulebook-EN_v02_Web.pdf?rlkey=9mz7tkbxgl9vyx4f9spbgmqnu&dl=0'
A='https://cdn.svc.asmodee.net/production-unboxnowcom/uploads/2022/04/en-azul-rules.pdf'
games={
'dragon_castle':dict(title='Dragon Castle',culture=bi('Chinese-inspired fantasy setting','受中国文化启发的奇幻世界'),recognition=['china','east_asia'],players='2–4',minutes='45',source='https://horribleguild.com/us/product/dragon-castle/',rules_url=D,
 description=bi('Build a new realm using tiles taken from a declining central castle. The setting draws on Chinese-inspired imagery through Mahjong-like pieces, dragons, shrines and architecture. Choose matching pieces, arrange groups and develop a layered structure. Your decisions determine how your realm grows and scores.','从逐渐衰落的中央城堡取走牌块，建造自己的新领地。游戏通过类似麻将的牌块、龙、神龛和建筑呈现受中国文化启发的意象。选择匹配的牌块，组合成组，发展多层结构。您的决策决定领地如何发展和得分。'),
 objective=bi('Earn the most victory points by building and consolidating groups and placing shrines.','通过建造领地、合并牌组和放置神龛，获得最多胜利分。'),
 components=bi('116 tiles, realm boards, central boards, shrines, point tokens, countdown tokens and optional Spirit/Dragon cards.','116块牌、领地板、中央板、神龛、分数标记、倒计时标记及可选的灵体／龙卡。'),
 sections=[
 (bi('Goal and pilot setup','目标与试做设置'),bi('Aim for the most points. The full game uses a central castle and personal realm boards. This pilot uses a fixed illustrated position and the official beginner setup without Spirit or Dragon cards. You will make three decisions rather than play a full game.','目标是获得最多分数。完整游戏使用中央城堡和个人领地板。本试做采用固定图示局面，并使用官方建议的不含灵体或龙卡的新手设置。您将做出三项决策，而非进行一整局游戏。'),'pp.2–3'),
 (bi('Choose an action','选择行动'),bi('First take an available tile from the highest remaining floor. A tile is available when at least one long side is free. Either take a second available tile with the identical symbol from any floor, take one shrine with the first tile, or discard the first tile for one point.','首先从当前最高层取一块可取的牌。至少一条长边没有相邻牌时，该牌可取。之后可从任意层取第二块图案完全相同的可取牌；或保留第一块牌并取一个神龛；或弃掉第一块牌获得1分。'),'p.5'),
 (bi('Place the tiles','放置牌块'),bi('Place collected tiles face up on empty spaces or on face-down tiles without shrines. Never cover a face-up tile or a shrine. Tiles do not need to be next to one another when placed.','将取得的牌正面朝上放在空位，或没有神龛的背面朝上的牌上。不可覆盖正面朝上的牌或神龛。新放的牌不必彼此相邻。'),'p.6'),
 (bi('Groups and points','牌组与分数'),bi('After placing your tiles, a group of at least four orthogonally connected tiles of one type must be flipped face down. Symbols within the type may differ. A four-tile group scores two points; a five-tile group scores three. Diagonal contact does not connect a group.','放好牌后，若同一类别的至少4块牌通过上下左右连接，必须将整组翻至背面。同类别内的图案可不同。4块一组得2分，5块一组得3分。对角接触不构成连接。'),'p.6'),
 (bi('Shrines','神龛'),bi('Immediately after consolidating, you may build one shrine on a faction group or up to two on a special group, using your supply. A Dragon group adds one point. Each shrine scores one, two or three points at game end on floor one, two or three-plus, respectively.','合并后可立即使用库存神龛：普通阵营牌组可放1个，特殊牌组最多2个。龙牌组额外得1分。游戏结束时，第一层、第二层、第三层及更高层的神龛分别值1、2、3分。'),'p.7'),
 (bi('Ending the game','游戏结束'),bi('When only ground-floor castle tiles remain, players may take a countdown token as their action. Revealing the exclamation mark triggers the final round; finish the round so turns are equal. Add group points, shrines and countdown tokens. The highest total wins.','城堡仅剩底层牌时，玩家可选择取倒计时标记作为行动。露出感叹号会触发最后一轮；完成该轮，使各玩家回合数相同。将牌组分、神龛分和倒计时标记分相加，总分最高者获胜。'),'p.9')],
 examples=[(bi('Example 1 · matching pieces','示例1 · 匹配牌块'),bi('After taking A (Merchant 2), B is a matching available Merchant 2. C is Merchant 3: the same type but a different symbol. D is Merchant 2 with both long sides blocked. B is the legal matching second tile.','取走A（商人2）后，B是可取的商人2。C是商人3：类别相同但图案不同。D是两条长边都被挡住的商人2。B是合法的第二块匹配牌。'),'p.5'),(bi('Example 2 · a group of four','示例2 · 四块牌组'),bi('Four connected Merchant tiles form one group even with different numbers. Consolidate the group for two points, then optionally build one shrine from your supply. A diagonal tile would not join the group.','4块上下左右相连的商人牌，即使数字不同，也组成一组。合并该组得2分，然后可使用库存放置1个神龛。仅对角相邻的牌不属于该组。'),'pp.6–7')],
 faq=[(bi('Must a pair match only by color?','一对牌只需颜色相同吗？'),bi('No. The symbols must match exactly. Consolidating a group uses type rather than identical symbols.','不是。图案必须完全相同。合并牌组时看类别，而不是图案是否完全相同。')),(bi('Do we use special card powers?','是否使用特殊卡牌能力？'),bi('No. This pilot uses the publisher’s recommended beginner setup.','不使用。本试做采用出版商建议的新手设置。'))],
 trials=[question('D_T1','A (Merchant 2) has been taken. Which candidate is a legal matching second tile?','已取走A（商人2）。哪块候选牌是合法的第二块匹配牌？',[('B: available Merchant 2','B：可取的商人2'),('C: available Merchant 3','C：可取的商人3'),('D: Merchant 2, both long sides blocked','D：商人2，两条长边均被挡住')],0,'p.5 Available/Identical Tiles'),question('D_T2','You kept the pair. Which location can receive a face-up tile?','您保留了这对牌。哪个位置可以放一块正面朝上的牌？',[('On a face-up tile','正面朝上的牌上'),('An empty realm space','领地空位'),('On a shrine','神龛上')],1,'p.6 Placing Tiles'),question('D_T3','Your placement completes exactly four connected Merchant tiles. How many group points do you gain, excluding shrines?','您的放置刚好完成4块上下左右相连的商人牌。不计神龛，该牌组得几分？',[('4 points','4分'),('1 point','1分'),('2 points','2分')],2,'p.6 Set Scoring')],
 quiz=[question('D_Q1','What determines the winner?','什么决定胜者？',[('The most collected tiles','收集牌块最多'),('The most victory points','胜利分最多'),('The first empty realm','最先清空领地')],1,'p.9 End of the Game'),question('D_Q2','Where must the first tile of a regular action come from?','常规行动的第一块牌必须来自哪里？',[('Any available tile on any floor','任意层的任意可取牌'),('Any blocked tile','任意被挡住的牌'),('An available tile on the highest remaining floor','当前最高层的一块可取牌')],2,'p.5 Taking an Action'),question('D_Q3','Which placement is forbidden?','哪种放置不被允许？',[('Covering a face-up tile','覆盖正面朝上的牌'),('Using an empty space','使用空位'),('Covering a face-down tile without a shrine','覆盖没有神龛的背面牌')],0,'p.6 Placing Tiles'),question('D_Q4','What happens to a connected four-tile group of one type?','同类别的4块上下左右相连牌组会怎样？',[('It remains face up and scores zero','保持正面且得0分'),('It must be consolidated and scores two group points','必须合并并得2分'),('It is always discarded for four points','总是弃掉并得4分')],1,'p.6 Consolidating a Set'),question('D_Q5','What triggers the final round?','什么触发最后一轮？',[('One player builds a shrine','一名玩家建造神龛'),('Someone takes any pair','有人取走任意一对牌'),('A countdown action reveals the exclamation mark','倒计时行动露出感叹号')],2,'p.9 Triggering the Final Round')]),
'azul':dict(title='Azul',culture=bi('Portuguese palace and azulejo tiles','葡萄牙宫殿与阿祖莱若瓷砖'),recognition=['portugal','europe'],players='2–4',minutes='30–45',source='https://www.asmodee.co.uk/collections/azul',rules_url=A,
 description=bi('Decorate a palace wall using colored tiles selected from shared displays. The setting draws on Portuguese azulejo tilework and the Royal Palace of Évora. Choose pieces, prepare matching lines and develop a patterned wall. Your decisions determine how your design grows and scores.','从公共展示盘选择彩色瓷砖，装饰宫殿墙面。游戏背景源自葡萄牙阿祖莱若瓷砖艺术与埃武拉王宫。选择瓷砖，准备同色图案行，逐步拼出墙面图案。您的决策决定设计如何发展和得分。'),
 objective=bi('Earn the most points by placing tiles on your wall and completing patterns.','通过在墙面放置瓷砖和完成图案，获得最多分数。'),components=bi('100 tiles in five colors, player boards, factory displays, scoring markers, a starting-player marker and a bag.','5种颜色共100块瓷砖、玩家板、工厂展示盘、计分标记、起始玩家标记和布袋。'),
 sections=[
 (bi('Goal and pilot setup','目标与试做设置'),bi('Aim for the most points. The full game uses a colored wall, pattern lines of one to five spaces and shared displays. This pilot uses a fixed illustrated position on the standard colored side. You will make three decisions rather than play a full game.','目标是获得最多分数。完整游戏使用彩色墙面、容量为1至5块的图案行及公共展示盘。本试做采用标准彩色面的固定图示局面。您将做出三项决策，而非进行一整局游戏。'),'printed pp.2–3'),
 (bi('Choose an action','选择行动'),bi('Take every tile of one color from one factory display; move its other colors to the center. Alternatively, take every tile of one color from the center. The first person taking from the center also takes the starting-player marker onto their floor line.','从一个工厂展示盘取走某一种颜色的全部瓷砖，将该盘其他颜色移至中央；也可从中央取走某一种颜色的全部瓷砖。该轮第一个从中央取砖的人，还需将起始玩家标记放入地板行。'),'printed p.3'),
 (bi('Place the tiles','放置瓷砖'),bi('Place a pick into one pattern line, with excess tiles going to the floor. A line may contain only one color. You cannot choose a line whose corresponding wall row already contains that color. Complete lines can later send one tile to the wall.','将一次取得的瓷砖放入同一个图案行，多余的放入地板行。每行只能容纳一种颜色。若对应墙面行已有该颜色，则不可选该图案行。完成的图案行随后可将一块瓷砖移至墙面。'),'printed pp.3–4'),
 (bi('Groups and points','图案与分数'),bi('When all shared tiles are taken, move one tile from each complete pattern line to its matching wall space, from top to bottom. An isolated tile scores one point. Connected tiles score the contiguous horizontal and vertical runs, counting the new tile in each qualifying direction.','公共瓷砖取完后，从上到下，将每个已完成图案行的一块瓷砖移至墙面对应颜色格。孤立瓷砖得1分。有相邻瓷砖时，分别计算连续的横向及纵向数量；每个符合方向都计入新瓷砖。'),'printed pp.4–5'),
 (bi('Floor and bonuses','地板扣分与奖励'),bi('Floor spaces impose their printed penalties, but the score never drops below zero. Remove the other tiles from completed pattern lines; keep incomplete lines. At game end, each complete wall row adds two points, each complete column seven, and all five tiles of one color ten.','地板行按格上标示扣分，但总分不低于0。移走已完成图案行的其余瓷砖；未完成行保留。游戏结束时，墙面每个完整横行加2分，每个完整竖列加7分，每种颜色放齐5块加10分。'),'printed p.5'),
 (bi('Ending the game','游戏结束'),bi('If no wall row is complete, refill displays and play another round. The game ends after the wall-tiling phase in which any player completes a horizontal wall row of five tiles. Add the end bonuses. The highest total wins; completed rows break a tied score.','若墙面仍没有完整横行，补充展示盘并进行下一轮。任意玩家完成一条5块瓷砖的墙面横行后，该轮铺墙阶段结束即结束游戏。加入结束奖励，总分最高者获胜；同分时完整横行较多者胜。'),'printed p.5')],
 examples=[(bi('Example 1 · selecting pieces','示例1 · 选择瓷砖'),bi('A display contains two blue tiles, one red and one yellow. Choosing blue takes both blue tiles; the other colors move to the center. An empty two-space pattern line can hold both when its wall row has no blue tile.','一个展示盘含2块蓝砖、1块红砖和1块黄砖。选择蓝色就取走2块蓝砖，其余移至中央。若对应墙面行没有蓝砖，空的两格图案行可容纳这2块蓝砖。'),'printed pp.3–4'),(bi('Example 2 · an isolated tile','示例2 · 孤立瓷砖'),bi('A completed two-space pattern line sends one blue tile to the matching wall space. With no adjacent wall tiles, it scores one point. The other tile goes to the box lid. No floor penalty applies in this example.','已完成的两格图案行将一块蓝砖移至墙面对应格。没有相邻墙砖时，该砖得1分。另一块移入盒盖。该例没有地板扣分。'),'printed pp.4–5')],
 faq=[(bi('May I split one pick across lines?','一次取得的瓷砖能分到多行吗？'),bi('No. Choose one pattern line; any excess goes to the floor.','不能。选择一个图案行，多余的放入地板行。')),(bi('Do incomplete lines clear each round?','未完成图案行每轮会清空吗？'),bi('No. Their tiles stay for the next round.','不会。未完成行的瓷砖留到下一轮。'))],
 trials=[question('A_T1','The display has two blue, one red and one yellow tile. If you choose blue, what do you take?','展示盘有2块蓝砖、1块红砖和1块黄砖。选择蓝色时取走哪些？',[('Just one blue tile','仅1块蓝砖'),('All four tiles','全部4块'),('Both blue tiles','2块蓝砖')],2,'printed p.3 Factory Offer'),question('A_T2','Where can both blue tiles fit without overflow? All listed wall rows have no blue tile.','哪里能放下2块蓝砖且不溢出？以下各行对应的墙面均无蓝砖。',[('An empty two-space pattern line','空的两格图案行'),('An empty one-space pattern line','空的一格图案行'),('A three-space line already containing red','已有红砖的三格图案行')],0,'printed pp.3–4 Pattern Lines'),question('A_T3','One blue tile moves to an isolated wall space. With no floor penalty, how many points does this tile score?','一块蓝砖移到孤立的墙面格。没有地板扣分，这块砖得几分？',[('1 point','1分'),('2 points','2分'),('0 points','0分')],0,'printed p.5 Scoring')],
 quiz=[question('A_Q1','What determines the winner?','什么决定胜者？',[('The most points','分数最多'),('The fewest colors','颜色最少'),('The fullest floor line','地板行最满')],0,'printed p.5 End of the Game'),question('A_Q2','What is a legal pick from one factory display?','从一个工厂展示盘取砖，哪种合法？',[('Any two different colors','任意两种不同颜色'),('Every tile of one chosen color','所选一种颜色的全部砖'),('Only one tile, always','始终只能取1块')],1,'printed p.3 Factory Offer'),question('A_Q3','When is a color forbidden in a pattern line?','什么时候某颜色不能放入一个图案行？',[('When that color appears on a different wall row','其他墙面行有该颜色'),('When that line is empty','该行为空'),('When the corresponding wall row already contains that color','对应墙面行已有该颜色')],2,'printed p.3 Pattern Lines'),question('A_Q4','How many points does an isolated new wall tile score before penalties?','不计扣分，新增的孤立墙砖得几分？',[('3 points','3分'),('1 point','1分'),('5 points','5分')],1,'printed p.5 Scoring'),question('A_Q5','When does the game end?','何时结束游戏？',[('After the wall-tiling phase when any horizontal wall row is completed','任意墙面横行完成后的该次铺墙阶段结束时'),('After the first tile is placed','放第一块砖后'),('Whenever a pattern line is full','任意图案行满时')],0,'printed p.5 End of the Game')])}
for gid,g in games.items():
 g['id']=gid; g['stimulus_version']='stimuli-3-ai-components-draft';g['rules_version']='rules-1-source-checked';g['access_date']='2026-11-24';g['price']=bi('CNY 299 · experimental price placeholder','人民币299元 · 实验价格暂定');g['price_is_placeholder']=True
