(ROOT/'config/games.json').write_text(json.dumps(games,ensure_ascii=False,indent=2)+'\n')
# All graphics below are original generic geometric schematics, not copied board layouts.
for gid in games:
 def svg(body,label):
  return f'<svg xmlns="http://www.w3.org/2000/svg" width="960" height="420" viewBox="0 0 960 420" role="img" aria-label="{escape(label)}"><rect width="960" height="420" rx="24" fill="#edf1ec"/><style>text{{font-family:Arial,sans-serif;fill:#233e36}}.tile{{fill:#fffdf5;stroke:#6d897d;stroke-width:3}}</style>{body}</svg>'
 def tile(x,y,label,color='#17645b'):
  return f'<rect class="tile" x="{x}" y="{y}" width="76" height="94" rx="9"/><text x="{x+38}" y="{y+57}" text-anchor="middle" font-size="25" style="fill:{color}">{escape(label)}</text>'
 if gid=='dragon_castle':
  body=''.join(tile(170+c*86,90+r*105,str((c+r)%3+1)) for r in range(2) for c in range(6))
  body+='<path d="M100 77 L480 22 L860 77 M150 77 H810" fill="none" stroke="#6d897d" stroke-width="9"/>'
  e1=''.join(tile(x,105,label) for x,label in [(100,'A: M2'),(310,'B: M2'),(520,'C: M3'),(730,'D: M2')])+'<text x="110" y="250" font-size="23">Taken</text><text x="310" y="250" font-size="23">Available</text><text x="520" y="250" font-size="23">Available</text><path d="M720 95 V215 M816 95 V215" stroke="#8d4a41" stroke-width="10"/><text x="730" y="250" font-size="23">Blocked</text>'
  e2=''.join(tile(200+i*86,120,f'M{i+1}') for i in range(4))+'<text x="640" y="175" font-size="42">→ 2 VP</text><text x="200" y="285" font-size="23">4 connected tiles of one type</text>'
 else:
  body=''.join(f'<rect x="{220+c*88}" y="{55+r*88}" width="74" height="74" rx="7" fill="{["#17645b","#b28b48","#526f8a"][(c+r)%3]}"/><path d="M{227+c*88} {92+r*88} l30 -27 l30 27 l-30 27 Z" fill="none" stroke="#fffdf5" stroke-width="3"/>' for r in range(3) for c in range(6))
  e1=''.join(tile(x,105,l,c) for x,l,c in [(130,'Blue','#526f8a'),(230,'Blue','#526f8a'),(330,'Red','#8d4a41'),(430,'Gold','#b28b48')])+'<text x="150" y="275" font-size="24">Choose blue: take both</text><path d="M610 145 H850" stroke="#6d897d" stroke-width="4"/>'+tile(630,95,'Blue','#526f8a')+tile(720,95,'Blue','#526f8a')
  e2=tile(180,120,'Blue','#526f8a')+tile(270,120,'Blue','#526f8a')+'<text x="410" y="180" font-size="38">→</text>'+tile(530,120,'Blue','#526f8a')+'<text x="650" y="175" font-size="42">1 point</text><text x="530" y="280" font-size="23">No adjacent wall tiles</text>'
 body+='<text x="480" y="385" text-anchor="middle" font-size="22">Original research schematic · commercial artwork not reproduced</text>'
 for kind,content in [('hero',body),('example1',e1),('example2',e2)]:
  (ROOT/f'assets/{gid}_{kind}.svg').write_text(svg(content,f'{games[gid]["title"]} {kind} schematic'))
